package com.acme.member.coupon;

/** 优惠券折扣类型。 */
public enum DiscountType {

    /** 按订单金额的百分比减免，例如 10 表示减 10%。 */
    PERCENTAGE,

    /** 固定金额减免，单位分。 */
    FIXED_AMOUNT;

    public boolean isPercentage() {
        return this == PERCENTAGE;
    }

    public boolean isFixedAmount() {
        return this == FIXED_AMOUNT;
    }
}

package com.acme.member.coupon;

/**
 * {@link DiscountType} 的命名兼容别名。
 *
 * <p>业务代码统一使用 {@link DiscountType}；保留这个枚举是为了让不同命名习惯的调用方
 * （PERCENT / PERCENT_OFF / FIXED 等）也能直接构造优惠券。
 */
public enum CouponType {

    PERCENTAGE,
    PERCENT,
    PERCENT_OFF,
    RATE,
    FIXED_AMOUNT,
    FIXED,
    AMOUNT;

    public DiscountType toDiscountType() {
        return switch (this) {
            case FIXED_AMOUNT, FIXED, AMOUNT -> DiscountType.FIXED_AMOUNT;
            case PERCENTAGE, PERCENT, PERCENT_OFF, RATE -> DiscountType.PERCENTAGE;
        };
    }
}

package com.acme.member.coupon;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.Collections;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * 优惠券。
 *
 * <p>折扣规则：
 * <ul>
 *   <li>{@link DiscountType#PERCENTAGE}：{@code discountValue} 是减免百分比，10 表示减 10%，
 *       计算结果按分四舍五入（HALF_UP）。</li>
 *   <li>{@link DiscountType#FIXED_AMOUNT}：{@code discountValue} 是减免金额（分），
 *       最多减到 0，不会出现负数应付金额。</li>
 * </ul>
 *
 * <p>使用限制：
 * <ul>
 *   <li>{@code validFrom} / {@code validUntil} 为 null 表示不限制；{@code validUntil} 不含边界。</li>
 *   <li>{@code maxUses <= 0} 表示不限次数；大于 0 时达到次数后不可再用。</li>
 * </ul>
 */
public class Coupon {

    private final String code;
    private final DiscountType discountType;
    private final long discountValue;
    private final long minAmountCents;
    private final LocalDateTime validFrom;
    private final LocalDateTime validUntil;
    private final int maxUses;

    private final Set<String> usedMembers = ConcurrentHashMap.newKeySet();
    private int usedCount;
    private boolean active = true;

    /** 百分比优惠券的快捷构造：{@code discountPercent} 表示减免百分比。 */
    public Coupon(String code, int discountPercent) {
        this(code, DiscountType.PERCENTAGE, discountPercent, 0L, null, null, 0);
    }

    public Coupon(String code, int discountPercent, LocalDateTime validUntil) {
        this(code, DiscountType.PERCENTAGE, discountPercent, 0L, null, validUntil, 0);
    }

    public Coupon(String code, int discountPercent, int maxUses) {
        this(code, DiscountType.PERCENTAGE, discountPercent, 0L, null, null, maxUses);
    }

    public Coupon(String code, int discountPercent, long minAmountCents, int maxUses) {
        this(code, DiscountType.PERCENTAGE, discountPercent, minAmountCents, null, null, maxUses);
    }

    /**
     * 折扣率构造：0.8 表示 8 折（减 20%）；大于 1 时按“减免百分比”解释（例如 20 表示减 20%）。
     */
    public Coupon(String code, double discountRate) {
        this(code, toPercentage(discountRate));
    }

    public Coupon(String code, BigDecimal discountRate) {
        this(code, toPercentage(Objects.requireNonNull(discountRate).doubleValue()));
    }

    public Coupon(String code, DiscountType discountType, long discountValue) {
        this(code, discountType, discountValue, 0L, null, null, 0);
    }

    public Coupon(String code, DiscountType discountType, long discountValue, LocalDateTime validUntil) {
        this(code, discountType, discountValue, 0L, null, validUntil, 0);
    }

    public Coupon(String code, DiscountType discountType, long discountValue,
                  long minAmountCents, LocalDateTime validFrom, LocalDateTime validUntil) {
        this(code, discountType, discountValue, minAmountCents, validFrom, validUntil, 0);
    }

    public Coupon(String code, DiscountType discountType, long discountValue, long minAmountCents,
                  LocalDateTime validFrom, LocalDateTime validUntil, int maxUses) {
        if (code == null || code.isBlank()) {
            throw new IllegalArgumentException("券码不能为空");
        }
        Objects.requireNonNull(discountType, "discountType");
        if (discountType == DiscountType.PERCENTAGE && (discountValue < 0 || discountValue > 100)) {
            throw new IllegalArgumentException("百分比折扣必须在 0–100 之间");
        }
        if (discountType == DiscountType.FIXED_AMOUNT && discountValue < 0) {
            throw new IllegalArgumentException("固定减免金额不能为负数");
        }
        if (minAmountCents < 0) {
            throw new IllegalArgumentException("最低消费金额不能为负数");
        }
        if (maxUses < 0) {
            throw new IllegalArgumentException("最大使用次数不能为负数");
        }
        if (validFrom != null && validUntil != null && validFrom.isAfter(validUntil)) {
            throw new IllegalArgumentException("优惠券生效时间不能晚于失效时间");
        }
        this.code = code.trim();
        this.discountType = discountType;
        this.discountValue = discountValue;
        this.minAmountCents = minAmountCents;
        this.validFrom = validFrom;
        this.validUntil = validUntil;
        this.maxUses = maxUses;
    }

    public Coupon(String code, CouponType couponType, long discountValue) {
        this(code, Objects.requireNonNull(couponType).toDiscountType(), discountValue);
    }

    public Coupon(String code, CouponType couponType, long discountValue, long minAmountCents,
                  LocalDateTime validFrom, LocalDateTime validUntil, int maxUses) {
        this(code, Objects.requireNonNull(couponType).toDiscountType(), discountValue,
                minAmountCents, validFrom, validUntil, maxUses);
    }

    public static Coupon percentage(String code, int discountPercent) {
        return new Coupon(code, DiscountType.PERCENTAGE, discountPercent);
    }

    public static Coupon percentOff(String code, int discountPercent) {
        return percentage(code, discountPercent);
    }

    public static Coupon rate(String code, double payRate) {
        return new Coupon(code, payRate);
    }

    public static Coupon fixedAmount(String code, long discountCents) {
        return new Coupon(code, DiscountType.FIXED_AMOUNT, discountCents);
    }

    public static Coupon fixed(String code, long discountCents) {
        return fixedAmount(code, discountCents);
    }

    private static int toPercentage(double discountRate) {
        double value;
        if (discountRate > 0d && discountRate <= 1d) {
            // 0.8 = 8 折 = 减 20%
            value = (1d - discountRate) * 100d;
        } else {
            value = discountRate;
        }
        if (value < 0d || value > 100d) {
            throw new IllegalArgumentException("折扣率必须在 0–1（支付比例）或 0–100（减免百分比）之间");
        }
        return (int) Math.round(value);
    }

    public String getCode() {
        return code;
    }

    public DiscountType getDiscountType() {
        return discountType;
    }

    public long getDiscountValue() {
        return discountValue;
    }

    public long getValue() {
        return discountValue;
    }

    public int getDiscountPercent() {
        return discountType == DiscountType.PERCENTAGE ? (int) discountValue : 0;
    }

    public long getMinAmountCents() {
        return minAmountCents;
    }

    public LocalDateTime getValidFrom() {
        return validFrom;
    }

    public LocalDateTime getValidUntil() {
        return validUntil;
    }

    public LocalDateTime getExpiresAt() {
        return validUntil;
    }

    public int getMaxUses() {
        return maxUses;
    }

    public synchronized int getUsedCount() {
        return usedCount;
    }

    public int getRemainingUses() {
        if (maxUses <= 0) {
            return Integer.MAX_VALUE;
        }
        return Math.max(0, maxUses - getUsedCount());
    }

    public Set<String> getUsedMembers() {
        return Collections.unmodifiableSet(usedMembers);
    }

    public synchronized boolean isActive() {
        return active;
    }

    public synchronized void setActive(boolean active) {
        this.active = active;
    }

    public synchronized boolean isUsableAt(LocalDateTime now) {
        if (!active) {
            return false;
        }
        if (validFrom != null && now.isBefore(validFrom)) {
            return false;
        }
        if (validUntil != null && !now.isBefore(validUntil)) {
            return false;
        }
        return maxUses <= 0 || usedCount < maxUses;
    }

    public boolean isExpiredAt(LocalDateTime now) {
        return validUntil != null && !now.isBefore(validUntil);
    }

    public boolean isNotStartedAt(LocalDateTime now) {
        return validFrom != null && now.isBefore(validFrom);

package com.acme.member.coupon;

/**
 * 优惠券校验/使用异常。
 *
 * <p>继承 {@link IllegalArgumentException}，既方便 Controller 统一映射为 400，
 * 也让调用方可以用更宽泛的参数异常类型捕获。
 */
public class CouponException extends IllegalArgumentException {

    private final String couponCode;

    public CouponException(String couponCode, String message) {
        super(message);
        this.couponCode = couponCode;
    }

    public String getCouponCode() {
        return couponCode;
    }
}

