package com.acme.member.coupon;

import org.springframework.stereotype.Repository;

import java.util.Collection;
import java.util.Locale;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

/** 内存优惠券仓储。券码大小写不敏感，前后空白会被忽略。 */
@Repository
public class CouponRepository {

    private final ConcurrentMap<String, Coupon> coupons = new ConcurrentHashMap<>();

    /** 默认带一批演示券，便于直接调用回调接口体验优惠。 */
    public CouponRepository() {
        this(true);
    }

    public CouponRepository(boolean seedDemoCoupons) {
        if (seedDemoCoupons) {
            CouponDefaults.seed(this);
        }
    }

    public Coupon save(Coupon coupon) {
        Coupon value = java.util.Objects.requireNonNull(coupon);
        coupons.put(normalize(value.getCode()), value);
        return value;
    }

    public Optional<Coupon> findByCode(String code) {
        if (code == null || code.isBlank()) {
            return Optional.empty();
        }
        return Optional.ofNullable(coupons.get(normalize(code)));
    }

    public Optional<Coupon> find(String code) {
        return findByCode(code);
    }

    public Optional<Coupon> get(String code) {
        return findByCode(code);
    }

    public boolean delete(String code) {
        if (code == null || code.isBlank()) {
            return false;
        }
        return coupons.remove(normalize(code)) != null;
    }

    public boolean remove(String code) {
        return delete(code);
    }

    public Collection<Coupon> findAll() {
        return coupons.values();
    }

    public long count() {
        return coupons.size();
    }

    public void clear() {
        coupons.clear();
    }

    public static String normalize(String code) {
        return code.trim().toUpperCase(Locale.ROOT);
    }
}

