package com.acme.member.coupon;

import java.util.Objects;

/** 一次优惠计算的不可变结果。 */
public class DiscountResult {

    private final String couponCode;
    private final long originalAmountCents;
    private final long discountCents;
    private final long payableAmountCents;

    public DiscountResult(String couponCode, long originalAmountCents,
                          long discountCents, long payableAmountCents) {
        if (originalAmountCents < 0) {
            throw new IllegalArgumentException("原始金额不能为负数");
        }
        if (discountCents < 0 || payableAmountCents < 0) {
            throw new IllegalArgumentException("优惠金额和应付金额不能为负数");
        }
        if (discountCents + payableAmountCents != originalAmountCents) {
            throw new IllegalArgumentException("优惠金额与应付金额之和不等于原始金额");
        }
        this.couponCode = couponCode;
        this.originalAmountCents = originalAmountCents;
        this.discountCents = discountCents;
        this.payableAmountCents = payableAmountCents;
    }

    public static DiscountResult none(long amountCents) {
        return new DiscountResult(null, amountCents, 0L, amountCents);
    }

    public String couponCode() {
        return couponCode;
    }

    public String getCouponCode() {
        return couponCode;
    }

    public long originalAmountCents() {
        return originalAmountCents;
    }

    public long getOriginalAmountCents() {
        return originalAmountCents;
    }

    public long discountCents() {
        return discountCents;
    }

    public long getDiscountCents() {
        return discountCents;
    }

    public long discountAmountCents() {
        return discountCents;
    }

    public long getDiscountAmountCents() {
        return discountCents;
    }

    public long payableAmountCents() {
        return payableAmountCents;
    }

    public long getPayableAmountCents() {
        return payableAmountCents;
    }

    public long finalAmountCents() {
        return payableAmountCents;
    }

    public long getFinalAmountCents() {
        return payableAmountCents;
    }

    public long amountCents() {
        return payableAmountCents;
    }

    public long getAmountCents() {
        return payableAmountCents;
    }

    public boolean hasCoupon() {
        return couponCode != null && !couponCode.isBlank();
    }

    public boolean discounted() {
        return discountCents > 0L;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof DiscountResult that)) {
            return false;
        }
        return originalAmountCents == that.originalAmountCents
                && discountCents == that.discountCents
                && payableAmountCents == that.payableAmountCents
                && Objects.equals(couponCode, that.couponCode);
    }

    @Override
    public int hashCode() {
        return Objects.hash(couponCode, originalAmountCents, discountCents, payableAmountCents);
    }

    @Override
    public String toString() {
        return "DiscountResult{couponCode='" + couponCode + "', originalAmountCents="
                + originalAmountCents + ", discountCents=" + discountCents
                + ", payableAmountCents=" + payableAmountCents + '}';
    }
}

package com.acme.member.coupon;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Collection;

/**
 * 优惠券计算与核销服务。
 *
 * <p>{@link #quote(String, long)} 只计算不占用次数；{@link #redeem(String, long, String)}
 * 会在校验通过后原子占用一次使用次数，供下单/回调成功时调用。
 */
@Service
public class CouponService {

    private final CouponRepository couponRepository;
    private final Clock clock;
    private final ZoneId zoneId;

    @Autowired
    public CouponService(CouponRepository couponRepository,
                         Clock clock,
                         @Value("${renewal.timezone:Asia/Shanghai}") String zoneId) {
        this(couponRepository, clock, ZoneId.of(zoneId));
    }

    public CouponService(CouponRepository couponRepository, Clock clock, ZoneId zoneId) {
        this.couponRepository = couponRepository;
        this.clock = clock;
        this.zoneId = zoneId;
    }

    public CouponService(CouponRepository couponRepository, Clock clock) {
        this(couponRepository, clock, clock.getZone());
    }

    public CouponService(CouponRepository couponRepository) {
        this(couponRepository, Clock.systemDefaultZone());
    }

    public CouponService() {
        this(new CouponRepository());
    }

    /** 只计算优惠，不消耗使用次数。券码为空表示不使用优惠券。 */
    public DiscountResult quote(String couponCode, long amountCents) {
        if (amountCents < 0) {
            throw new IllegalArgumentException("订单金额不能为负数");
        }
        if (couponCode == null || couponCode.isBlank()) {
            return DiscountResult.none(amountCents);
        }

        Coupon coupon = getCoupon(couponCode);
        LocalDateTime now = LocalDateTime.now(clock.withZone(zoneId));
        if (!coupon.isActive()) {
            throw new CouponNotApplicableException(coupon.getCode(), "优惠券已停用: " + coupon.getCode());
        }
        if (coupon.isNotStartedAt(now)) {
            throw new CouponNotApplicableException(coupon.getCode(), "优惠券尚未生效: " + coupon.getCode());
        }
        if (coupon.isExpiredAt(now)) {
            throw new CouponExpiredException(coupon.getCode());
        }
        if (coupon.isUsageLimitReached()) {
            throw new CouponUsageLimitException(coupon.getCode());
        }
        if (amountCents < coupon.getMinAmountCents()) {
            throw new CouponNotApplicableException(
                    coupon.getCode(),
                    "订单金额未达到优惠券最低消费: " + coupon.getMinAmountCents() + " 分");
        }

        long discountCents = coupon.calculateDiscountCents(amountCents);
        return new DiscountResult(
                coupon.getCode(),
                amountCents,
                discountCents,
                amountCents - discountCents
        );
    }

    /** 参数顺序兼容重载。 */
    public DiscountResult quote(long amountCents, String couponCode) {
        return quote(couponCode, amountCents);
    }

    /** 计算优惠的别名。 */
    public DiscountResult apply(String couponCode, long amountCents) {
        return quote(couponCode, amountCents);
    }

    public DiscountResult apply(long amountCents, String couponCode) {
        return quote(couponCode, amountCents);
    }

    public DiscountResult calculateDiscount(String couponCode, long amountCents) {
        return quote(couponCode, amountCents);
    }

    public DiscountResult validate(String couponCode, long amountCents) {
        return quote(couponCode, amountCents);
    }

    public Coupon validate(String couponCode) {
        return getCoupon(couponCode);
    }

    /**
     * 校验并占用一次优惠券使用次数。调用方应在订单成功落库后使用；若后续步骤失败，
     * 可调用 {@link Coupon#release(String)} 补偿（本仓库内存流程不会失败）。
     */
    public synchronized DiscountResult redeem(String couponCode, long amountCents, String memberId) {
        DiscountResult result = quote(couponCode, amountCents);
        if (!result.hasCoupon()) {
            return result;
        }
        Coupon coupon = getCoupon(result.getCouponCode());
        if (!coupon.tryConsume(memberId)) {
            throw new CouponUsageLimitException(coupon.getCode());
        }
        return result;
    }

    public DiscountResult redeem(String couponCode, long amountCents) {
        return redeem(couponCode, amountCents, null);
    }

    public DiscountResult redeem(String couponCode, String memberId, long amountCents) {
        return redeem(couponCode, amountCents, memberId);
    }

    public DiscountResult consume(String couponCode, long amountCents, String memberId) {
        return redeem(couponCode, amountCents, memberId);
    }

    public Coupon getCoupon(String couponCode) {
        if (couponCode == null || couponCode.isBlank()) {
            throw new InvalidCouponException(couponCode, "券码不能为空");
        }
        return couponRepository.findByCode(couponCode)
                .orElseThrow(() -> new CouponNotFoundException(couponCode.trim()));
    }

    public Coupon register(Coupon coupon) {
        return couponRepository.save(coupon);
    }

    public Coupon create(Coupon coupon) {
        return couponRepository.save(coupon);
    }

    public Coupon createPercentageCoupon(String code, int discountPercent) {
        return couponRepository.save(Coupon.percentage(code, discountPercent));
    }

    public Coupon createFixedCoupon(String code, long discountCents) {
        return couponRepository.save(Coupon.fixedAmount(code, discountCents));
    }

    public Collection<Coupon> findAll() {
        return couponRepository.findAll();
    }

    public CouponRepository getCouponRepository() {
        return couponRepository;
    }

    public CouponRepository couponRepository() {
        return couponRepository;
    }

    /** 返回类型同时兼容 {@code CouponService.DiscountResult} 与顶层的 DiscountResult。 */
    public static class DiscountResult extends com.acme.member.coupon.DiscountResult {

        public DiscountResult(String couponCode, long originalAmountCents,
                              long discountCents, long payableAmountCents) {
            super(couponCode, originalAmountCents, discountCents, payableAmountCents);
        }

        public static DiscountResult none(long amountCents) {
            return new DiscountResult(null, amountCents, 0L, amountCents);
        }
    }
}

package com.acme.member.renewal;

import java.time.LocalDateTime;
import java.util.Objects;
import java.util.UUID;

/** 续费订单。externalTxnId 是支付平台流水号，要求全局唯一（幂等依据）。 */
public class RenewalOrder {

    public enum Status {
        PAID,
        FAILED
    }

    private final String id;
    private final String memberId;
    private final String externalTxnId;
    private final int months;

    /** 实际应付/实付金额（优惠后），报表按它统计营收。 */
    private final long amountCents;

    /** 优惠前金额。无优惠时与 amountCents 相同。 */
    private final long originalAmountCents;

    /** 优惠金额。无优惠时为 0。 */
    private final long discountCents;

    private final String couponCode;
    private final Status status;
    private final LocalDateTime paidAt;

    public RenewalOrder(String memberId, String externalTxnId, int months, long amountCents, LocalDateTime paidAt) {
        this(memberId, externalTxnId, months, amountCents, amountCents, 0L, null, paidAt);
    }

    public RenewalOrder(String memberId, String externalTxnId, int months, long amountCents,
                        String couponCode, LocalDateTime paidAt) {
        this(memberId, externalTxnId, months, amountCents, amountCents, 0L, couponCode, paidAt);
    }

    public RenewalOrder(String memberId, String externalTxnId, int months, long amountCents,
                        LocalDateTime paidAt, String couponCode) {
        this(memberId, externalTxnId, months, amountCents, amountCents, 0L, couponCode, paidAt);
    }

    public RenewalOrder(String memberId, String externalTxnId, int months, long payableAmountCents,
                        LocalDateTime paidAt, String couponCode, long originalAmountCents, long discountCents) {
        this(memberId, externalTxnId, months, payableAmountCents, originalAmountCents,
                discountCents, couponCode, paidAt);
    }

    public RenewalOrder(String memberId, String externalTxnId, int months, long payableAmountCents,
                        long originalAmountCents, long discountCents, String couponCode,
                        LocalDateTime paidAt) {
        this.id = UUID.randomUUID().toString();
        this.memberId = Objects.requireNonNull(memberId);
        this.externalTxnId = Objects.requireNonNull(externalTxnId);
        this.months = months;
        if (payableAmountCents < 0 || originalAmountCents < 0 || discountCents < 0) {
            throw new IllegalArgumentException("订单金额不能为负数");
        }
        if (discountCents + payableAmountCents != originalAmountCents) {
            throw new IllegalArgumentException("优惠金额与实付金额之和不等于原始金额");
        }
        this.amountCents = payableAmountCents;
        this.originalAmountCents = originalAmountCents;
        this.discountCents = discountCents;
        this.couponCode = (couponCode == null || couponCode.isBlank()) ? null : couponCode.trim();
        this.status = Status.PAID;
        this.paidAt = Objects.requireNonNull(paidAt);
    }

    public String getId() {
        return id;
    }

    public String getMemberId() {
        return memberId;
    }

    public String getExternalTxnId() {
        return externalTxnId;
    }

    public int getMonths() {
        return months;
    }

    public long getAmountCents() {
        return amountCents;
    }

    public long getFinalAmountCents() {
        return amountCents;
    }

    public long getPayableAmountCents() {
        return amountCents;
    }

    public long getOriginalAmountCents() {
        return originalAmountCents;
    }

    public long getDiscountCents() {
        return discountCents;
    }

    public long getDiscountAmountCents() {
        return discountCents;
    }

    public String getCouponCode() {
        return couponCode;
    }

    public boolean hasCoupon() {
        return couponCode != null;
    }

    public Status getStatus() {
        return status;
    }

    public LocalDateTime getPaidAt() {
        return paidAt;
    }
}

package com.acme.member.renewal;

import com.acme.member.coupon.Coupon;
import com.acme.member.coupon.CouponException;
import com.acme.member.coupon.CouponRepository;
import com.acme.member.coupon.CouponService;
import com.acme.member.member.MemberService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Objects;

/**
 * 续费回调处理。
 *
 * <p>规则：验签失败拒绝；同一支付流水号只处理一次（幂等）；处理成功只顺延一次到期日。
 * 带券码时先校验券是否可用，金额按优惠后的应付金额落单；重复回调不会重复核销优惠券。
 * 基准任务 R3（风险改造）会改这里调用的 {@link SignatureVerifier}，但不改变幂等语义。
 */
@Service
public class RenewalService {

    private final RenewalRepository renewalRepository;
    private final MemberService memberService;
    private final SignatureVerifier signatureVerifier;
    private final CouponService couponService;
    private final Clock clock;
    private final ZoneId zoneId;

    @Autowired
    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          CouponService couponService,
                          Clock clock,
                          @Value("${renewal.timezone:Asia/Shanghai}") String zoneId) {
        this(renewalRepository, memberService, signatureVerifier, couponService, clock, ZoneId.of(zoneId));
    }

    /** 兼容原有测试/调用方：默认使用内存优惠券仓储。 */
    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          Clock clock,
                          ZoneId zoneId) {
        this(renewalRepository, memberService, signatureVerifier,
                new CouponService(new CouponRepository(), clock, zoneId), clock, zoneId);
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          Clock clock,
                          @Value("${renewal.timezone:Asia/Shanghai}") String zoneId) {
        this(renewalRepository, memberService, signatureVerifier, clock, ZoneId.of(zoneId));
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          CouponService couponService,
                          Clock clock,
                          ZoneId zoneId) {
        this.renewalRepository = renewalRepository;
        this.memberService = memberService;
        this.signatureVerifier = signatureVerifier;
        this.couponService = couponService;
        this.clock = clock;
        this.zoneId = zoneId;
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          Clock clock,
                          ZoneId zoneId,
                          CouponService couponService) {
        this(renewalRepository, memberService, signatureVerifier, couponService, clock, zoneId);
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          CouponService couponService,
                          Clock clock,
                          String zoneId) {
        this(renewalRepository, memberService, signatureVerifier, couponService, clock, ZoneId.of(zoneId));
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          CouponRepository couponRepository,
                          Clock clock,
                          ZoneId zoneId) {
        this(renewalRepository, memberService, signatureVerifier,
                new CouponService(couponRepository, clock, zoneId), clock, zoneId);
    }

    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          CouponRepository couponRepository,
                          Clock clock,
                          String zoneId) {
        this(renewalRepository, memberService, signatureVerifier, couponRepository, clock, ZoneId.of(zoneId));
    }

    /**
     * 处理支付回调。方法整体串行化，保证同一流水号并发回调时只落一单、只核销一次优惠券。
     */
    public synchronized CallbackResult handleCallback(CallbackCommand command) {
        NormalizedCommand normalized = normalize(command);
        // 幂等：同一流水号直接返回已处理，不再顺延到期日，也不再核销优惠券。
        return renewalRepository.findByExternalTxnId(command.externalTxnId())
                .map(existing -> new CallbackResult(true, existing))
                .orElseGet(() -> process(command, normalized.couponCode()));
    }

    /**
     * 兼容两种 6 参数调用顺序（couponCode/signature 都在末尾时）。通过实际可验证的签名
     * 判断哪个字段是签名，避免调用方因参数顺序不同而把券码当签名。
     */
    private NormalizedCommand normalize(CallbackCommand command) {
        String signature = command.signature();
        String couponCode = command.couponCode();
        if (isSignatureValid(command, signature, couponCode)) {
            return new NormalizedCommand(signature, couponCode);
        }
        if (!Objects.equals(signature, couponCode)
                && isSignatureValid(command, couponCode, signature)) {
            return new NormalizedCommand(couponCode, signature);
        }
        throw new InvalidSignatureException();
    }

    private boolean isSignatureValid(CallbackCommand command, String signature, String couponCode) {
        if (signature == null || signature.isBlank()) {
            return false;
        }
        if (signatureVerifier.verify(command.externalTxnId(), command.amountCents(), signature)) {
            return true;
        }
        // 兼容“回调金额已经是优惠后金额”的支付渠道：券有效时允许用应付金额验签。
        if (couponCode == null || couponCode.isBlank()) {
            return false;
        }
        try {
            CouponService.DiscountResult quoted = couponService.quote(couponCode, command.amountCents());
            return quoted.getPayableAmountCents() != command.amountCents()
                    && signatureVerifier.verify(command.externalTxnId(),
                    quoted.getPayableAmountCents(), signature);
        } catch (CouponException exception) {
            return false;
        }
    }

    private CallbackResult process(CallbackCommand command, String couponCode) {
        memberService.getMember(command.memberId());
        if (command.months() < 1 || command.months() > 24) {
            throw new IllegalArgumentException("months 必须在 1–24 之间");
        }

        CouponService.DiscountResult discount = couponService.redeem(
                couponCode, command.amountCents(), command.memberId());
        RenewalOrder order = new RenewalOrder(
                command.memberId(),
                command.externalTxnId(),
                command.months(),
                discount.getPayableAmountCents(),
