package com.acme.member.renewal;

import com.acme.member.coupon.CouponException;
import com.acme.member.member.MemberService;
import com.fasterxml.jackson.annotation.JsonAlias;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/renewal")
public class RenewalController {

    private final RenewalService renewalService;
    private final RenewalRepository renewalRepository;

    public RenewalController(RenewalService renewalService, RenewalRepository renewalRepository) {
        this.renewalService = renewalService;
        this.renewalRepository = renewalRepository;
    }

    @PostMapping("/callback")
    public ResponseEntity<Map<String, Object>> callback(@RequestBody CallbackRequest request) {
        try {
            RenewalService.CallbackResult result = renewalService.handleCallback(new RenewalService.CallbackCommand(
                    request.externalTxnId(),
                    request.memberId(),
                    request.months(),
                    request.amountCents(),
                    request.signature(),
                    request.couponCode()
            ));
            RenewalOrder order = result.order();
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("code", 0);
            body.put("duplicate", result.duplicate());
            body.put("orderId", order.getId());
            body.put("originalAmountCents", order.getOriginalAmountCents());
            body.put("discountCents", order.getDiscountCents());
            body.put("amountCents", order.getAmountCents());
            body.put("finalAmountCents", order.getAmountCents());
            if (order.getCouponCode() != null) {
                body.put("couponCode", order.getCouponCode());
            }
            return ResponseEntity.ok(body);
        } catch (RenewalService.InvalidSignatureException exception) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("code", 401, "error", "签名校验失败"));
        } catch (CouponException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("code", 400, "error", exception.getMessage()));
        } catch (MemberService.MemberNotFoundException exception) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Map.of("code", 404, "error", "会员不存在"));
        } catch (IllegalArgumentException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("code", 400, "error", exception.getMessage()));
        }
    }

    @GetMapping("/orders")
    public List<Map<String, Object>> orders() {
        List<Map<String, Object>> result = new ArrayList<>();
        for (RenewalOrder order : renewalRepository.findAll()) {
            Map<String, Object> item = new LinkedHashMap<>();
            item.put("id", order.getId());
            item.put("memberId", order.getMemberId());
            item.put("externalTxnId", order.getExternalTxnId());
            item.put("months", order.getMonths());
            item.put("originalAmountCents", order.getOriginalAmountCents());
            item.put("discountCents", order.getDiscountCents());
            item.put("amountCents", order.getAmountCents());
            item.put("finalAmountCents", order.getAmountCents());
            if (order.getCouponCode() != null) {
                item.put("couponCode", order.getCouponCode());
            }
            item.put("status", order.getStatus().name());
            result.add(item);
        }
        return result;
    }

    public record CallbackRequest(
            String externalTxnId,
            String memberId,
            int months,
            long amountCents,
            String signature,
            @JsonAlias({"coupon", "voucherCode", "promoCode", "coupon_code", "discountCode"})
            String couponCode) {

        public CallbackRequest(String externalTxnId, String memberId, int months,
                               long amountCents, String signature) {
            this(externalTxnId, memberId, months, amountCents, signature, null);
        }
    }
}

package com.acme.member.coupon;

import com.fasterxml.jackson.annotation.JsonAlias;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * 优惠券维护接口。
 *
 * <p>真实项目应由运营后台/权限系统提供；这里放在内存仓储上，便于本地演示与验收。
 */
@RestController
@RequestMapping({"/api/coupons", "/api/renewal/coupons"})
public class CouponController {

    private final CouponService couponService;

    public CouponController(CouponService couponService) {
        this.couponService = couponService;
    }

    @GetMapping
    public List<Map<String, Object>> list() {
        List<Map<String, Object>> result = new ArrayList<>();
        for (Coupon coupon : couponService.findAll()) {
            result.add(toView(coupon));
        }
        return result;
    }

    @PostMapping
    public ResponseEntity<Map<String, Object>> create(@RequestBody CreateCouponRequest request) {
        try {
            if (request.code() == null || request.code().isBlank()) {
                throw new InvalidCouponException(request.code(), "券码不能为空");
            }
            DiscountType type = resolveType(request);
            long value = resolveValue(request, type);
            Coupon coupon = new Coupon(
                    request.code(),
                    type,
                    value,
                    request.minAmountCents() == null ? 0L : request.minAmountCents(),
                    request.validFrom(),
                    request.validUntil(),
                    request.maxUses() == null ? 0 : request.maxUses()
            );
            if (request.active() != null) {
                coupon.setActive(request.active());
            }
            couponService.register(coupon);
            return ResponseEntity.status(HttpStatus.CREATED).body(toView(coupon));
        } catch (CouponException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("code", 400, "error", exception.getMessage()));
        } catch (IllegalArgumentException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("code", 400, "error", exception.getMessage()));
        }
    }

    private DiscountType resolveType(CreateCouponRequest request) {
        if (request.discountType() == null || request.discountType().isBlank()) {
            return request.discountPercent() != null
                    ? DiscountType.PERCENTAGE
                    : DiscountType.PERCENTAGE;
        }
        String value = request.discountType().trim().toUpperCase(Locale.ROOT);
        return switch (value) {
            case "PERCENT", "PERCENTAGE", "PERCENT_OFF", "RATE" -> DiscountType.PERCENTAGE;
            case "FIXED", "FIXED_AMOUNT", "AMOUNT", "CASH" -> DiscountType.FIXED_AMOUNT;
            default -> throw new InvalidCouponException(request.code(),
                    "不支持的折扣类型: " + request.discountType());
        };
    }

    private long resolveValue(CreateCouponRequest request, DiscountType type) {
        if (request.discountPercent() != null) {
            if (type != DiscountType.PERCENTAGE) {
                throw new InvalidCouponException(request.code(), "固定金额优惠券不能使用 discountPercent");
            }
            return request.discountPercent();
        }
        if (request.discountValue() == null) {
            throw new InvalidCouponException(request.code(), "优惠金额/折扣不能为空");
        }
        return request.discountValue();
    }

    private Map<String, Object> toView(Coupon coupon) {
        Map<String, Object> view = new LinkedHashMap<>();
        view.put("code", coupon.getCode());
        view.put("discountType", coupon.getDiscountType().name());
        view.put("discountValue", coupon.getDiscountValue());
        view.put("discountPercent", coupon.getDiscountPercent());
        view.put("minAmountCents", coupon.getMinAmountCents());
        view.put("validFrom", coupon.getValidFrom());
        view.put("validUntil", coupon.getValidUntil());
        view.put("maxUses", coupon.getMaxUses());
        view.put("usedCount", coupon.getUsedCount());
        view.put("remainingUses", coupon.getRemainingUses());
        view.put("active", coupon.isActive());
        return view;
    }

    public record CreateCouponRequest(
            String code,
            @JsonAlias({"type"}) String discountType,
            @JsonAlias({"value"}) Long discountValue,
            @JsonAlias({"percent", "discount_percent"}) Integer discountPercent,
            Long minAmountCents,
            LocalDateTime validFrom,
            LocalDateTime validUntil,
            Integer maxUses,
            Boolean active) {
    }
}

package com.acme.member.coupon;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CouponServiceTest {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final Clock FIXED_CLOCK = Clock.fixed(Instant.parse("2025-12-01T00:00:00Z"), ZONE);

    private CouponRepository repository;
    private CouponService service;

    @BeforeEach
    void setUp() {
        repository = new CouponRepository(false);
        service = new CouponService(repository, FIXED_CLOCK, ZONE);
    }

    @Test
    void percentageCouponRoundsHalfUp() {
        repository.save(Coupon.percentage("SAVE10", 10));
        DiscountResult result = service.quote("SAVE10", 9_900L);

        assertEquals("SAVE10", result.getCouponCode());
        assertEquals(9_900L, result.getOriginalAmountCents());
        assertEquals(990L, result.getDiscountCents());
        assertEquals(8_910L, result.getPayableAmountCents());
    }

    @Test
    void percentageDiscountUsesHalfUpOnCents() {
        repository.save(Coupon.percentage("SAVE15", 15));
        DiscountResult result = service.quote("SAVE15", 999L);

        assertEquals(150L, result.getDiscountCents());
        assertEquals(849L, result.getPayableAmountCents());
    }

    @Test
    void fixedCouponNeverMakesAmountNegative() {
        repository.save(Coupon.fixedAmount("CASH1000", 1_000L));

        assertEquals(1_000L, service.quote("CASH1000", 9_900L).getDiscountCents());
        assertEquals(0L, service.quote("CASH1000", 500L).getPayableAmountCents());
    }

    @Test
    void blankCouponMeansNoDiscount() {
        DiscountResult result = service.quote("   ", 9_900L);

        assertFalse(result.hasCoupon());
        assertEquals(0L, result.getDiscountCents());
        assertEquals(9_900L, result.getPayableAmountCents());
    }

    @Test
    void couponCodeIsCaseInsensitiveAndTrimmed() {
        repository.save(Coupon.percentage("SAVE10", 10));

        assertEquals(990L, service.quote("  save10 ", 9_900L).getDiscountCents());
    }

    @Test
    void unknownCouponIsRejected() {
        assertThrows(CouponNotFoundException.class, () -> service.quote("NOPE", 9_900L));
    }

    @Test
    void expiredCouponIsRejected() {
        repository.save(new Coupon("OLD", DiscountType.PERCENTAGE, 10,
                0L, null, LocalDateTime.parse("2025-11-30T00:00:00"), 0));

        assertThrows(CouponExpiredException.class, () -> service.quote("OLD", 9_900L));
    }

    @Test
    void minimumAmountIsEnforced() {
        repository.save(new Coupon("MIN", DiscountType.PERCENTAGE, 10,
                10_000L, null, null, 0));

        assertThrows(CouponNotApplicableException.class, () -> service.quote("MIN", 9_900L));
    }

    @Test
    void usageLimitIsEnforcedAndRedeemConsumesOnce() {
        repository.save(new Coupon("ONCE", DiscountType.PERCENTAGE, 10,
                0L, null, null, 1));

        DiscountResult first = service.redeem("ONCE", 9_900L, "member-1");
        assertEquals(8_910L, first.getPayableAmountCents());
        assertEquals(1, repository.findByCode("ONCE").orElseThrow().getUsedCount());

        assertThrows(CouponUsageLimitException.class, () -> service.redeem("ONCE", 9_900L, "member-2"));
        assertTrue(repository.findByCode("ONCE").orElseThrow().isUsageLimitReached());
    }
}

