private long resolveValue(CreateCouponRequest request, DiscountType type) {
    if (request.rate() != null) {
        if (type != DiscountType.PERCENTAGE) {
            throw new InvalidCouponException(request.code(), "固定金额优惠券不能使用 rate");
        }
        double rate = request.rate();
        double percent = rate > 0d && rate <= 1d ? (1d - rate) * 100d : rate;
        if (percent < 0d || percent > 100d) {
            throw new InvalidCouponException(request.code(), "rate 必须在 0–1 或 0–100 之间");
        }
        return Math.round(percent);
    }
    if (request.discountPercent() != null) {
        if (type != DiscountType.PERCENTAGE) {
            throw new InvalidCouponException(request.code(), "固定金额优惠券不能使用 discountPercent");
        }
        return request.discountPercent();
    }
    if (request.discountValue() == null) {
        throw new InvalidCouponException(request.code(), "优惠金额/折扣不能为空");
    }
    return request.discountValue();
}

